/* Forward declaration for k_p4wq_submit, which is typically in <zephyr/kernel.h> */
extern void k_p4wq_submit(struct k_p4wq_work *work, k_p4wq_work_handler_t handler);

/**
 * @brief Internal wrapper for k_p4wq_work_handler_t to call rtio_work_submit_t.
 *
 * This function is called by the k_p4wq workqueue when the work item is processed.
 * It extracts the original rtio_work_req and calls its handler.
 *
 * @param work Pointer to the k_p4wq_work item.
 */
static inline void z_rtio_work_req_p4wq_handler(struct k_p4wq_work *work)
{
	struct rtio_work_req *req = CONTAINER_OF(work, struct rtio_work_req, work);

	/* Execute the user-provided RTIO work handler */
	req->handler(req->iodev_sqe);

	/* The work item is released by rtio_executor_ok/err after the handler completes.
	 * So, no need to free req here.
	 */
}

/**
 * @brief Submit RTIO work request.
 *
 * @param req Item to fill with request information.
 * @param iodev_sqe RTIO Operation information.
 * @param handler Callback to handler where work operation is performed.
 */
static inline void rtio_work_req_submit(struct rtio_work_req *req,
					struct rtio_iodev_sqe *iodev_sqe,
					rtio_work_submit_t handler)
{
	/* Handle NULL request gracefully to prevent segmentation faults */
	if (req == NULL) {
		return;
	}

	/* Fill the request structure with the provided information */
	req->iodev_sqe = iodev_sqe;
	req->handler = handler;

	/* Submit the work item to the priority-based workqueue */
	k_p4wq_submit(&req->work, z_rtio_work_req_p4wq_handler);
}
