/* Define the memory slab for rtio_work_req items */
K_MEM_SLAB_DEFINE(rtio_work_req_slab, sizeof(struct rtio_work_req),
		  CONFIG_RTIO_WORKQ_POOL_ITEMS, 4);

/* Define the RTIO workqueue */
K_P4WQ_DEFINE(rtio_workq,
	      CONFIG_RTIO_WORKQ_THREADS_POOL,
	      CONFIG_RTIO_WORKQ_THREADS_POOL_STACK_SIZE,
	      CONFIG_RTIO_WORKQ_THREADS_POOL_PRIO);

static void rtio_work_handler_wrapper(struct k_p4wq_work *work)
{
	struct rtio_work_req *req = CONTAINER_OF(work, struct rtio_work_req, work);

	if (req->handler != NULL) {
		req->handler(req->iodev_sqe);
	}

	/* Release the work item back to the slab */
	k_mem_slab_free(&rtio_work_req_slab, (void **)&req);
}

struct rtio_work_req *rtio_work_req_alloc(void)
{
	struct rtio_work_req *req;

	if (k_mem_slab_alloc(&rtio_work_req_slab, (void **)&req, K_NO_WAIT) == 0) {
		return req;
	}

	return NULL;
}

void rtio_work_req_submit(struct rtio_work_req *req,
			  struct rtio_iodev_sqe *iodev_sqe,
			  rtio_work_submit_t handler)
{
	if (req == NULL) {
		return;
	}

	req->iodev_sqe = iodev_sqe;
	req->handler = handler;

	k_p4wq_submit(&rtio_workq, &req->work, rtio_work_handler_wrapper);
}

uint32_t rtio_work_req_used_count_get(void)
{
	return CONFIG_RTIO_WORKQ_POOL_ITEMS - k_mem_slab_num_free_get(&rtio_work_req_slab);
}

